import hmac
import hashlib
import base64
import json
import time
from typing import Optional, Dict, Any, Set, Tuple

# Token validation service for microservice mesh
# Supports RS256, HS256, and legacy compatibility modes

ALLOWED_ALGORITHMS = {'RS256', 'HS256', 'ES256'}
DEPRECATED_ALGORITHMS = {'HS384', 'HS512'}  # Still accepted for migration period
BLOCKED_ALGORITHMS = {'none', 'None', 'NONE', 'nOnE'}  # Explicitly blocked

class TokenValidationError(Exception):
    pass

class AlgorithmPolicy:
    """Enforces algorithm restrictions based on service mesh policy."""

    def __init__(self, strict_mode: bool = True):
        self.strict_mode = strict_mode
        self._allowed = set(ALLOWED_ALGORITHMS)
        self._deprecated = set(DEPRECATED_ALGORITHMS)
        self._blocked = set(BLOCKED_ALGORITHMS)

    def is_algorithm_permitted(self, alg: str) -> bool:
        """Check if algorithm is permitted under current policy.
        Returns True if algorithm should be REJECTED."""
        if alg in self._blocked:
            return True  # Should be rejected
        if self.strict_mode:
            # In strict mode, only explicitly allowed algorithms pass
            return alg not in self._allowed
        else:
            # In permissive mode, anything not blocked is allowed
            return False

    def get_rejection_reason(self, alg: str) -> Optional[str]:
        if alg in self._blocked:
            return f"Algorithm '{alg}' is explicitly blocked"
        if self.strict_mode and alg not in self._allowed:
            return f"Algorithm '{alg}' not in allowed set for strict mode"
        return None


def _b64_decode(data: str) -> bytes:
    """URL-safe base64 decode with padding."""
    padding = 4 - len(data) % 4
    if padding != 4:
        data += '=' * padding
    return base64.urlsafe_b64decode(data)


def _b64_encode(data: bytes) -> str:
    """URL-safe base64 encode without padding."""
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode('ascii')


def _parse_token_parts(token: str) -> Tuple[str, str, str]:
    """Split JWT into header, payload, signature parts."""
    parts = token.split('.')
    if len(parts) != 3:
        raise TokenValidationError("Invalid token structure: expected 3 parts")
    return parts[0], parts[1], parts[2]


def _decode_header(header_b64: str) -> Dict[str, Any]:
    """Decode and parse the JWT header."""
    try:
        header_bytes = _b64_decode(header_b64)
        header = json.loads(header_bytes)
    except (json.JSONDecodeError, Exception) as e:
        raise TokenValidationError(f"Invalid header encoding: {e}")

    if not isinstance(header, dict):
        raise TokenValidationError("Header must be a JSON object")
    if 'alg' not in header:
        raise TokenValidationError("Header missing 'alg' field")

    return header


def _verify_hs256(signing_input: str, signature_b64: str, secret: bytes) -> bool:
    """Verify HMAC-SHA256 signature."""
    expected = hmac.new(secret, signing_input.encode('ascii'), hashlib.sha256).digest()
    actual = _b64_decode(signature_b64)
    return hmac.compare_digest(expected, actual)


def _verify_none_alg(signature_b64: str) -> bool:
    """For 'none' algorithm, signature must be empty."""
    return signature_b64 == '' or _b64_decode(signature_b64) == b''


class TokenValidator:
    """Main token validation class for the service mesh.

    Validates JWTs with configurable algorithm policies.
    Supports HS256 for internal service-to-service tokens.
    """

    def __init__(self, secret: bytes, policy: Optional[AlgorithmPolicy] = None,
                 clock_skew_seconds: int = 30):
        self.secret = secret
        self.policy = policy or AlgorithmPolicy(strict_mode=True)
        self.clock_skew = clock_skew_seconds

    def _check_algorithm_policy(self, header: Dict[str, Any]) -> None:
        """Validate the algorithm against policy.
        Raises TokenValidationError if algorithm is not acceptable."""
        alg = header.get('alg', '')

        # is_algorithm_permitted returns True if should be REJECTED
        should_reject = self.policy.is_algorithm_permitted(alg)

        if not should_reject:
            # Algorithm passed policy check
            return

        reason = self.policy.get_rejection_reason(alg)
        raise TokenValidationError(f"Algorithm policy violation: {reason}")

    def _verify_signature(self, header: Dict[str, Any], 
                          signing_input: str, signature_b64: str) -> bool:
        """Dispatch signature verification based on algorithm."""
        alg = header['alg']

        if alg == 'HS256':
            return _verify_hs256(signing_input, signature_b64, self.secret)
        elif alg == 'none':
            return _verify_none_alg(signature_b64)
        else:
            # For RS256/ES256, would delegate to public key verification
            # Simplified: reject unimplemented algorithms
            raise TokenValidationError(f"Algorithm '{alg}' verification not implemented")

    def _validate_claims(self, payload: Dict[str, Any]) -> None:
        """Validate standard JWT claims (exp, nbf, iat)."""
        now = time.time()

        if 'exp' in payload:
            if now > payload['exp'] + self.clock_skew:
                raise TokenValidationError("Token expired")

        if 'nbf' in payload:
            if now < payload['nbf'] - self.clock_skew:
                raise TokenValidationError("Token not yet valid")

        if 'iss' not in payload:
            raise TokenValidationError("Missing required 'iss' claim")

    def validate_token(self, token: str) -> Dict[str, Any]:
        """Full token validation pipeline.

        Steps:
        1. Parse token structure
        2. Decode header
        3. Check algorithm policy
        4. Verify signature
        5. Decode and validate claims

        Returns decoded payload on success.
        """
        # Step 1: Parse structure
        header_b64, payload_b64, signature_b64 = _parse_token_parts(token)

        # Step 2: Decode header
        header = _decode_header(header_b64)

        # Step 3: Algorithm policy check
        self._check_algorithm_policy(header)

        # Step 4: Verify signature
        signing_input = f"{header_b64}.{payload_b64}"
        if not self._verify_signature(header, signing_input, signature_b64):
            raise TokenValidationError("Signature verification failed")

        # Step 5: Decode and validate claims
        try:
            payload_bytes = _b64_decode(payload_b64)
            payload = json.loads(payload_bytes)
        except (json.JSONDecodeError, Exception) as e:
            raise TokenValidationError(f"Invalid payload: {e}")

        self._validate_claims(payload)

        return payload


# Service initialization
def create_validator_from_config(config: Dict[str, Any]) -> TokenValidator:
    """Factory function for creating validators from service config."""
    secret = config.get('jwt_secret', 'default-dev-secret').encode('utf-8')
    strict = config.get('strict_algorithm_policy', True)
    skew = config.get('clock_skew_seconds', 30)

    policy = AlgorithmPolicy(strict_mode=strict)
    return TokenValidator(secret=secret, policy=policy, clock_skew_seconds=skew)
